do $amoy_archive_observers_proof$
declare
  spec constant jsonb:=$archive_observer_proof_spec${"targets":[{"oid":24934,"signature":"bx1_portal.record_funding_observation(uuid,jsonb)","sha":"582cf7ae3a77c986b66ba500c556445af34aa05cb227a83622242d3705785b54","metadata":{"oid":"24934","proacl":["postgres=X/postgres","service_role=X/postgres"],"probin":null,"procost":100,"prokind":"f","prolang":"13619","proname":"record_funding_observation","prorows":0,"pronargs":2,"proowner":"16388","proconfig":["search_path=\"\""],"proretset":false,"prosecdef":true,"prorettype":"3802","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["eid","facts"],"proargtypes":["2950","3802"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":"24138","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0},"cuts":[{"name":"funding_pair","from":"source_urls is distinct from array['https://polygon-amoy-bor-rpc.publicnode.com','https://polygon-amoy.drpc.org']::text[]","to":"(source_urls is distinct from array['https://polygon-amoy-bor-rpc.publicnode.com','https://polygon-amoy.drpc.org']::text[]\n    and source_urls is distinct from array['https://polygon-amoy.drpc.org','https://polygon-amoy.gateway.tenderly.co']::text[])","count":1}]},{"oid":33625,"signature":"bx1_portal.fund_setup_observers_valid(jsonb)","sha":"bfc4c603e62cc227707a115cb04943d69564cd3cf6a5e324f3c2f6ea347374b2","metadata":{"oid":"33625","proacl":["postgres=X/postgres"],"probin":null,"procost":100,"prokind":"f","prolang":"13619","proname":"fund_setup_observers_valid","prorows":0,"pronargs":1,"proowner":"16388","proconfig":["search_path=\"\""],"proretset":false,"prosecdef":false,"prorettype":"16","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["result"],"proargtypes":["3802"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"i","proleakproof":false,"pronamespace":"24138","proallargtypes":null,"proargdefaults":null,"pr