e","prorows":0,"pronargs":1,"proowner":"16388","proconfig":["search_path=\"\""],"proretset":false,"prosecdef":false,"prorettype":"16","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["result"],"proargtypes":["3802"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"i","proleakproof":false,"pronamespace":"24138","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0},"cuts":[{"name":"recipient_shape_member","from":"provider->>'url' not in ('https://polygon-amoy.drpc.org','https://polygon-amoy-bor-rpc.publicnode.com')","to":"provider->>'url' not in ('https://polygon-amoy.drpc.org','https://polygon-amoy-bor-rpc.publicnode.com','https://polygon-amoy.gateway.tenderly.co')","count":1},{"name":"recipient_shape_pair","from":"if urls[1]=urls[2] then return false;end if;","to":"if urls[1]=urls[2] or ('https://polygon-amoy.drpc.org'=any(urls)) is not true then return false;end if;","count":1}]},{"oid":36709,"signature":"bx1_portal.record_fund_recipient_observation(jsonb,jsonb)","sha":"e6f18caacdd33227ffb2219c5b88ffa38f92da135ba5b9306bc2c6b8cb87391b","metadata":{"oid":"36709","proacl":["postgres=X/postgres","bx1_fund_execution_worker=X/postgres"],"probin":null,"procost":100,"prokind":"f","prolang":"13619","proname":"record_fund_recipient_observation","prorows":0,"pronargs":2,"proowner":"16388","proconfig":["search_path=\"\""],"proretset":false,"prosecdef":true,"prorettype":"3802","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["request","result"],"proargtypes":["3802","3802"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":"24138","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0},"cuts":[{"name":"recipient_record_member","from":"item->>'url' not in ('https://polygon-amoy.drpc.org','https://polygon-amoy-bor-rpc.publicnode.com')","to":"item->>'url' not in ('https://polygon-amoy.drpc.org','https://polygon-amoy-bor-rpc.publicnode.com','https://polygon-amoy.gateway.tenderly.co')","count":1},{"name":"recipient_record_pair","from":"if urls[1]=urls[2] then raise exception 'fund_recipient_duplicate_provider_denied';end if;","to":"if urls[1]=urls[2] or ('https://polygon-amoy.drpc.org'=any(urls)) is not true then raise exception 'fund_recipient_duplicate_provider_denied';end if;","count":1}]}],"dependency":{"oid":31534,"signature":"bx1_portal.record_fund_observation(uuid,jsonb)","sha":"59f356c8435b06d174bdd104563b0d471cd36772bfbf5c13ff14dac68a140bdf","metadata":{"oid":"31534","proacl":["postgres=X/postgres","bx1_fund_execution_worker=X/postgres"],"probin":null,"procost":100,"prokind":"f","prolang":"13619","proname":"record_fund_observation","prorows":0,"pronargs":2,"proowner":"16388","proconfig":["search_path=\"\""],"proretset":false,"prosecdef":true,"prorettype":"3802","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["oid","observation"],"proargtypes":["2950","3802"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":"24138","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0}}}$archive_observer_proof_spec$::jsonb;
  cases constant jsonb:=$archive_observer_cases$[{"name":"legacy ordered","providers":[{"url":"https://polygon-amoy.drpc.org","finalized_block_number":"100","finalized_block_hash":"0x1111111111111111111111111111111111111111111111111111111111111111"},{"url":"https://polygon-amoy-bor-rpc.publicnode.com","finalized_block_number":"100","finalized_block_hash":"0x1111111111111111111111111111111111111111111111111111111111111111"}],"valid":true,"ordered":true},{"name":"legacy reversed","providers":[{"url":"https://polygon-amoy-bor-rpc.publicnode.com","finalized_block_number":"100","finalized_block_hash":"0x1111111111111111111111111111111111111111111111111111111111111111"},{"url":"https://polygon-amoy.drpc.org","finalized_block_number":"100","finalized_block_hash":"0x1111111111111111111111111111111111111111111111111111111111111111"}],"valid":true,"ordered":false},{"name":"archive ordered","providers":[{"url":"https://polygon-amoy.drpc.org","finalized_block_number":"100","finalized_block_hash":"0x1111111111111111111111111111111111111111111111111111111111111111"},{"url":"https://polygon-amoy.gateway.tenderly.co","finalized_block_number":"100","finalized_block_hash":"0x1111111111111111111111111111111111111111111111111111111111111111"}],"valid":true,"ordered":true},{"name":"archive reversed","providers":[{"url":"https://polygon-amoy.gateway.tenderly.co","finalized_block_number":"100","finalized_block_hash":"0x1111111111111111111111111111111111111111111111111111111111111111"},{"url":"https://polygon-amoy.drpc.org","finalized_block_number":"100","finalized_block_hash":"0x1111111111111111111111111111111111111111111111111111111111111111"}],"valid":true,"ordered":false},{"name":"no dRPC","providers":[{"url":"https://polygon-amoy-bor-rpc.publicnode.com","finalized_block_number":"100","finalized_block_hash":"0x1111111111111111111111111111111111111111111111111111111111111111"},{"url":"https://polygon-amoy.gateway.tenderly.co","finalized_block_number":"100","finalized_block_hash":"0x1111111111111111111111111111111111111111111111111111111111111111"}],"valid":false,"ordered":false},{"name":"no dRPC reversed","providers":[{"url":"https://polygon-amoy.gateway.tenderly.co","finalized_block_number":"100","finalized_block_hash":"0x1111111111111111111111111111111111111111111111111111111111111111"},{"url":"https://polygon-amoy-bor-rpc.publicnode.com","finalized_block_number":"100","finalized_block_hash":"0x1111111111111111111111111111111111111111111111111111111111111111"}],"valid":false,"ordered":false},{"name":"duplicate 0","providers":[{"url":"https://polygon-amoy.drpc.org","finalized_block_number":"100","finalized_block_hash":"0x1111111111111111111111111111111111111111111111111111111111111111"},{"url":"https://polygon-amoy.drpc.org","finalized_block_number":"100","finalized_block_hash":"0x1111111111111111111111111111111111111111111111111111111111111111"}],"valid":false,"ordered":false},{"name":"duplicate 1","providers":[{"url":"https://polygon-amoy-bor-rpc.publicnode.com","finalized_block_number":"100","finalized_block_hash":"0x1111111111111111111111111111111111111111111111111111111111111111"},{"url":"https://polygon-amoy-bor-rpc.publicnode.com","finalized_block_number":"100","finalized_block_hash":"0x1111111111111111111111111111111111111111111111111111111111111111"}],"valid":false,"ordered":false},{"name":"duplicate 2","providers":[{"url":"https://polygon-amoy.gateway.tenderly.co","finalized_block_number":"100","finalized_block_hash":"0x1111111111111111111111111111111111111111111111111111111111111111"},{"url":"https://polygon-amoy.gateway.tenderly.co","finalized_block_number":"100","finalized_block_hash":"0x1111111111111111111111111111111111111111111111111111111111111111"}],"valid":false,"ordered":false},{"name":"foreign","providers":[{"url":"https://polygon-amoy.drpc.org","finalized_block_number":"100","finalized_block_hash":"0x1111111111111111111111111111111111111111111111111111111111111111"},{"url":"https://rpc.example.invalid","finalized_block_number":"100","finalized_block_hash":"0x1111111111111111111111111111111111111111111111111111111111111111"}],"valid":false,"ordered":false},{"name":"credentials","providers":[{"url":"https://polygon-amoy.drpc.org","finalized_block_number":"100","finalized_block_hash":"0x1111111111111111111111111111111111111111111111111111111111111111"},{"url":"https://user:pass@polygon-amoy.gateway.tenderly.co","finalized_block_number":"100","finalized_block_hash":"0x1111111111111111111111111111111111111111111111111111111111111111"}],"valid":false,"ordered":false},{"name":"query","providers":[{"url":"https://polygon-amoy.drpc.org","finalized_block_number":"100","finalized_block_hash":"0x1111111111111111111111111111111111111111111111111111111111111111"},{"url":"https://polygon-amoy.gateway.tenderly.co?key=fixture","finalized_block_number":"100","finalized_block_hash":"0x1111111111111111111111111111111111111111111111111111111111111111"}],"valid":false,"ordered":false},{"name":"extra provider","providers":[{"url":"https://polygon-amoy.drpc.org","finalized_block_number":"100","finalized_block_hash":"0x1111111111111111111111111111111111111111111111111111111111111111"},{"url":"https://polygon-amoy-bor-rpc.publicnode.com","finalized_block_number":"100","finalized_block_hash":"0x1111111111111111111111111111111111111111111111111111111111111111"},{"url":"https://polygon-amoy.gateway.tenderly.co","finalized_block_number":"100","finalized_block_hash":"0x1111111111111111111111111111111111111111111111111111111111111111"}],"valid":false,"ordered":false},{"name":"single provider","providers":[{"url":"https://polygon-amoy.drpc.org","finalized_block_number":"100","finalized_block_hash":"0x1111111111111111111111111111111111111111111111111111111111111111"}],"valid":false,"ordered":false},{"name":"empty providers","providers":[],"valid":false,"ordered":false},{"name":"null URL","providers":[{"url":"https://polygon-amoy.drpc.org","finalized_block_number":"100","finalized_block_hash":"0x1111111111111111111111111111111111111111111111111111111111111111"},{"url":null,"finalized_block_number":"100","finalized_block_hash":"0x1111111111111111111111111111111111111111111111111111111111111111"}],"valid":false,"ordered":false},{"name":"missing URL","providers":[{"url":"https://polygon-amoy.drpc.org","finalized_block_number":"100","finalized_block_hash":"0x1111111111111111111111111111111111111111111111111111111111111111"},{"finalized_block_number":"100","finalized_block_hash":"0x1111111111111111111111111111111111111111111111111111111111111111"}],"valid":false,"ordered":false},{"name":"null providers","providers":null,"valid":false,"ordered":false},{"name":"missing providers","valid":false,"ordered":false}]$archive_observer_cases$::jsonb;
  recipient_base constant jsonb:='{"version":1,"chain_id":80002,"expiry_enforced_on_chain":false,"operation_revision":1,"phase":"CREATE_IDENTITY","status":"UNKNOWN","transaction_hash":"0x1111111111111111111111111111111111111111111111111111111111111111","claim_data_hash":"0x2222222222222222222222222222222222222222222222222222222222222222","claim_id":"0x3333333333333333333333333333333333333333333333333333333333333333","operation_id":"11111111-1111-4111-8111-111111111111","expectation_hash":"4444444444444444444444444444444444444444444444444444444444444444","identity_address":"0x5555555555555555555555555555555555555555"}'::jsonb;
  target_spec jsonb;cut jsonb;metadata jsonb;sample jsonb;providers jsonb;setup_value jsonb;recipient_value jsonb;
  installed text;original text;rebuilt text;funding_predicate text;admission_predicate text;recipient_member text;recipient_pair text;
  source_urls text[];actual boolean;expected boolean;start_at integer;end_at integer;case_count integer:=0;cut_count integer:=0;
  claims_before text:=pg_catalog.current_setting('request.jwt.claims',true);
  sub_before text:=pg_catalog.current_setting('request.jwt.claim.sub',true);
begin
  if current_user<>'postgres' or session_user<>'postgres' or auth.uid() is not null
    or bx1_private.test_roleplay_environment() is not true then
    raise exception 'archive_proof_test_owner_without_claims_required' using errcode='42501';end if;
  if jsonb_array_length(spec->'targets')<>5 or jsonb_array_length(cases)<>19 then raise exception 'archive_proof_scope_changed';end if;
  select to_jsonb(p) into metadata from pg_catalog.pg_proc p where p.oid=(spec#>>'{dependency,oid}')::oid;
  if metadata-'prosrc' is distinct from spec#>'{dependency,metadata}'
    or encode(sha256(convert_to(metadata->>'prosrc','UTF8')),'hex') is distinct from spec#>>'{dependency,sha}' then
    raise exception 'archive_proof_unchanged_writer_changed';end if;
  for target_spec in select value from jsonb_array_elements(spec->'targets') loop
    select to_jsonb(p) into metadata from pg_catalog.pg_proc p where p.oid=(target_spec->>'oid')::oid;
    if metadata is null or metadata-'prosrc' is distinct from target_spec->'metadata' then raise exception 'archive_proof_metadata_changed';end if;
    installed:=metadata->>'prosrc';original:=installed;
    for cut in select value from jsonb_array_elements(target_spec->'cuts') with ordinality item(value,position) order by position desc loop
      if (length(original)-length(replace(original,cut->>'to','')))/length(cut->>'to')<>1 then
        raise exception 'archive_proof_reverse_cut_not_unique';end if;
      original:=replace(original,cut->>'to',cut->>'from');cut_count:=cut_count+1;
    end loop;
    if encode(sha256(convert_to(original,'UTF8')),'hex') is distinct from target_spec->>'sha' then raise exception 'archive_proof_original_changed';end if;
    rebuilt:=original;
    for cut in select value from jsonb_array_elements(target_spec->'cuts') loop
      if (length(rebuilt)-length(replace(rebuilt,cut->>'from','')))/length(cut->>'from')<>1 then raise exception 'archive_proof_forward_cut_not_unique';end if;
      rebuilt:=replace(rebuilt,cut->>'from',cut->>'to');
    end loop;
    if rebuilt is distinct from installed then raise exception 'archive_proof_rebuild_changed';end if;
    if target_spec->>'oid'='24934' then
      funding_predicate:=target_spec#>>'{cuts,0,to}';
      if strpos(installed,funding_predicate)=0 then raise exception 'archive_proof_funding_predicate_missing';end if;
      funding_predicate:=replace(funding_predicate,'source_urls','$1::text[]');
    elsif target_spec->>'oid'='36424' then
      start_at:=strpos(installed,'    or candidate#>>''{observed,providers,0,url}''');
      if start_at=0 then raise exception 'archive_proof_admission_predicate_missing';end if;
      admission_predicate:=substring(installed from start_at);
      end_at:=strpos(admission_predicate,E'\n    or expiry<=');
      if end_at=0 then raise exception 'archive_proof_admission_predicate_end_missing';end if;
      admission_predicate:=regexp_replace(substring(admission_predicate from 1 for end_at-1),'^[[:space:]]*or[[:space:]]+','');
      admission_predicate:=replace(admission_predicate,'candidate','$1::jsonb');
    elsif target_spec->>'oid'='36709' then
      recipient_member:=target_spec#>>'{cuts,0,to}';
      recipient_pair:=target_spec#>>'{cuts,1,to}';
      if strpos(installed,recipient_member)=0 or strpos(installed,recipient_pair)=0 then raise exception 'archive_proof_recipient_predicate_missing';end if;
      recipient_member:=replace(recipient_member,'item->>''url''','entry.url');
      recipient_pair:=split_part(split_part(recipient_pair,'if ',2),' then',1);
      recipient_pair:=replace(recipient_pair,'urls','$1::text[]');
    end if;
  end loop;
  if cut_count<>8 or funding_predicate is null or admission_predicate is null or recipient_pair is null then
    raise exception 'archive_proof_extraction_incomplete';end if;
  -- These are the two actual IMMUTABLE/INVOKER JSON-only validators, not writers.
  -- Existing cardinality/URL-type/finality metadata checks remain in their bodies.
  for sample in select value from jsonb_array_elements(cases) loop
    providers:=sample->'providers';expected:=(sample->>'valid')::boolean;
    setup_value:=jsonb_build_object('block_number','99');
    recipient_value:=recipient_base;
    if sample?'providers' then
      setup_value:=setup_value||jsonb_build_object('providers',providers);
      recipient_value:=recipient_value||jsonb_build_object('providers',providers);
    end if;
    if bx1_portal.fund_setup_observers_valid(setup_value) is distinct from expected
      or bx1_portal.fund_recipient_result_shape(recipient_value) is distinct from expected then
      raise exception 'archive_proof_pure_validator_case_failed: %',sample->>'name';end if;
    if jsonb_typeof(providers)='array' then
      select array_agg(entry->>'url' order by entry->>'url') into source_urls from jsonb_array_elements(providers) entry;
    else source_urls:=null;end if;
    execute 'select not ('||funding_predicate||')' into actual using source_urls;
    if actual is distinct from expected then raise exception 'archive_proof_funding_pair_case_failed: %',sample->>'name';end if;
    -- The ordinary admission writer is intentionally ordered: dRPC must remain
    -- provider0; legacy PublicNode or the new Tenderly source is provider1.
    execute 'select case when jsonb_typeof($1::jsonb#>''{observed,providers}'') is distinct from ''array'' then false else not ('||admission_predicate||') end'
      into actual using jsonb_build_object('observed',jsonb_build_object('providers',providers));
    if actual is distinct from (sample->>'ordered')::boolean then raise exception 'archive_proof_ordered_admission_case_failed: %',sample->>'name';end if;
    execute 'select case when cardinality($1::text[])<>2 or $1::text[] is null or array_position($1::text[],null) is not null then false '
      ||'when exists(select 1 from unnest($1::text[]) entry(url) where '||recipient_member||') then false else not ('||recipient_pair||') end'
      into actual using source_urls;
    if actual is distinct from expected then raise exception 'archive_proof_recipient_record_pair_case_failed: %',sample->>'name';end if;
    case_count:=case_count+1;
  end loop;
  if case_count<>19 then raise exception 'archive_proof_cases_missing';end if;
  if pg_catalog.current_setting('request.jwt.claims',true) is distinct from claims_before
    or pg_catalog.current_setting('request.jwt.claim.sub',true) is distinct from sub_before or auth.uid() is not null then
    raise exception 'archive_proof_claims_changed';end if;
end $amoy_archive_observers_proof$;
